{"cells": [{"cell_type": "markdown", "metadata": {}, "source": ["# Movie Recommendation System\nThis notebook demonstrates a simple movie recommender using genres."]}, {"cell_type": "code", "execution_count": 1, "metadata": {}, "outputs": [], "source": ["import pandas as pd\n", "from sklearn.feature_extraction.text import CountVectorizer\n", "from sklearn.metrics.pairwise import cosine_similarity\n\n", "df = pd.read_csv('movie_data.csv')\n", "df"]}, {"cell_type": "code", "execution_count": 2, "metadata": {}, "outputs": [], "source": ["vectorizer = CountVectorizer()\n", "genre_matrix = vectorizer.fit_transform(df['genre'])\n", "similarity = cosine_similarity(genre_matrix)\n", "\n", "def recommend(movie_title):\n", "    if movie_title not in df['title'].values:\n", "        return ['Movie not found']\n", "    idx = df[df['title']==movie_title].index[0]\n", "    scores = list(enumerate(similarity[idx]))\n", "    scores = sorted(scores, key=lambda x: x[1], reverse=True)[1:6]\n", "    return df['title'].iloc[[i[0] for i in scores]].tolist()\n", "\n", "recommend('Inception')"]}], "metadata": {"kernelspec": {"display_name": "Python", "language": "python", "name": "python3"}, "language_info": {"name": "python"}}, "nbformat": 4, "nbformat_minor": 5}